CREATE procedure MM_SP_ConsultarDocAnexosPorSolPed --14180	@IdSolicitudPedido INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN	SELECT d.IdDocAnexoPeticionOferta, d.NomDocumento, p.RazonSocial	FROM dbo.MM_DocAnexosPeticionOferta d		INNER JOIN dbo.MM_PeticionOferta po ON po.IdPeticionOferta = d.IdPeticionOferta		INNER JOIN dbo.MM_SolicitudPedido s ON s.IdSolicitudPedido = po.IdSolicitudPedido		INNER JOIN dbo.S_Proveedor p ON p.IdProveedor = po.IdSubcontratista	WHERE s.IdSolicitudPedido = @IdSolicitudPedido		AND d.Eliminado = 0END